  "CREATE TABLE `platform_version_archive_ref` (\n\t`owner_id` integer NOT NULL,\n\t`field` text NOT NULL,\n\t`archive_id` integer NOT NULL,\n\t`sealed` integer DEFAULT 0 NOT NULL,\n\tPRIMARY KEY(`owner_id`, `field`),\n\tFOREIGN KEY (`owner_id`) REFERENCES `platform_business_record_version`(`id`) ON UPDATE no action ON DELETE restrict,\n\tFOREIGN KEY (`archive_id`) REFERENCES `platform_archive_value`(`id`) ON UPDATE no action ON DELETE restrict,\n\tCONSTRAINT \"platform_version_archive_ref_ck\" CHECK(\"platform_version_archive_ref\".\"field\" = 'canonicalRawJson' AND \"platform_version_archive_ref\".\"sealed\" IN (0,1))\n)",
  "CREATE TABLE \"reconciliation_result\" (\n\t`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,\n\t`title_code` text NOT NULL,\n\t`enterprise_id` integer NOT NULL,\n\t`direction` text NOT NULL,\n\t`curated` integer DEFAULT false NOT NULL,\n\t`evidence` text,\n\tFOREIGN KEY (`title_code`) REFERENCES `title`(`code`) ON UPDATE no action ON DELETE no action,\n\tFOREIGN KEY (`enterprise_id`) REFERENCES `enterprise`(`id`) ON UPDATE no action ON DELETE no action\n)",
  "CREATE TABLE \"record\" (\n\t`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,\n\t`enterprise_id` integer NOT NULL,\n\t`title_code` text NOT NULL,\n\t`source` text NOT NULL,\n\t`district` text,\n\t`uscc_raw` text,\n\t`name_raw` text,\n\t`quality_flags` text DEFAULT '[]',\n\tFOREIGN KEY (`enterprise_id`) REFERENCES `enterprise`(`id`) ON UPDATE no action ON DELETE no action,\n\tFOREIGN KEY (`title_code`) REFERENCES `title`(`code`) ON UPDATE no action ON DELETE no action\n)",
  "CREATE TABLE `record_correspondence` (\n\t`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,\n\t`edge_key` text NOT NULL,\n\t`type` text NOT NULL,\n\t`role` text NOT NULL,\n\t`event_id` integer,\n\t`predecessor_event_id` integer,\n\t`observation_id` integer,\n\t`export_row_id` integer,\n\t`enterprise_id` integer,\n\t`title_code` text NOT NULL,\n\t`status` text NOT NULL,\n\t`revision` integer NOT NULL,\n\t`target_identity` text NOT NULL,\n\t`provenance` text NOT NULL,\n\t`source_fingerprint` text NOT NULL,\n\t`rule_id` text NOT NULL,\n\t`rule_version` text NOT NULL,\n\t`created_at` text NOT NULL,\n\t`decided_at` text,\n\t`ended_at` text,\n\tFOREIGN KEY (`event_id`) REFERENCES `record_event`(`id`) ON UPDATE no action ON DELETE no action,\n\tFOREIGN KEY (`predecessor_event_id`) REFERENCES `record_event`(`id`) ON UPDATE no action ON DELETE no action,\n\tFOREIGN KEY (`observation_id`) REFERENCES platform_business_observation(`id`) ON UPDATE no action ON DELETE no action,\n\tFOREIGN KEY (`export_row_id`) REFERENCES `platform_export_row`(`id`) ON UPDATE no action ON DELETE no action,\n\tFOREIGN KEY (`enterprise_id`) REFERENCES `enterprise`(`id`) ON UPDATE no action ON DELETE no action,\n\tFOREIGN KEY (`title_code`) REFERENCES `title`(`code`) ON UPDATE no action ON DELETE no action\n)",
  "CREATE TABLE `record_correspondence_audit` (\n\t`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,\n\t`correspondence_id` integer NOT NULL,\n\t`batch_id` integer NOT NULL,\n\t`idempotency_key` text NOT NULL,\n\t`from_status` text,\n\t`to_status` text NOT NULL,\n\t`expected_revision` integer NOT NULL,\n\t`resulting_revision` integer NOT NULL,\n\t`actor_type` text NOT NULL,\n\t`actor_id` text NOT NULL,\n\t`basis` text NOT NULL,\n\t`rule_id` text NOT NULL,\n\t`rule_version` text NOT NULL,\n\t`evidence` text NOT NULL,\n\t`decided_at` text NOT NULL,\n\tFOREIGN KEY (`correspondence_id`) REFERENCES `record_correspondence`(`id`) ON UPDATE no action ON DELETE no action,\n\tFOREIGN KEY (`batch_id`) REFERENCES `import_batch`(`id`) ON UPDATE no action ON DELETE no action\n)",
  "CREATE TABLE `record_event` (\n\t`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,\n\t`record_id` integer NOT NULL,\n\t`event_type` text NOT NULL,\n\t`year` integer,\n\t`batch_seq` integer,\n\t`sort_key` integer DEFAULT 0 NOT NULL, `review_outcome` text, `decided_year` integer, `revision` integer DEFAULT 1 NOT NULL, formal_validity TEXT,\n\tFOREIGN KEY (`record_id`) REFERENCES `record`(`id`) ON UPDATE no action ON DELETE cascade\n)",
